    public sealed class IndependentContentBuildResult { public bool Succeeded,Unchanged;public string PrefabPath,RecipeHash,BuildHash;public ValidationReport Report=new ValidationReport(); }

    public static class IndependentContentCompiler
    {
        public const string CompilerVersion="planned-independent-2";
        private static bool sharedReady;
        public static IndependentContentBuildResult BuildAsset(string recipePath)
        {
            var absolute=Absolute(recipePath);if(!File.Exists(absolute)){var missing=new IndependentContentBuildResult();missing.Report.Add("E1830",ValidationSeverity.Error,"/recipe","Independent content Recipe is missing.");return missing;}return BuildCore(recipePath,File.ReadAllText(absolute),null);
        }

        public static IndependentContentBuildResult BuildJsonForTransaction(string recipePath,string json){return BuildCore(recipePath,json,recipePath);}

        private static IndependentContentBuildResult BuildCore(string recipePath,string json,string sourceOverride)
        {
            var result=new IndependentContentBuildResult();if(!sharedReady){VfxStyleSharedLibrary.EnsureAll();sharedReady=true;}var catalog=VfxCompiler.LoadFormalCatalog();result.Report.AddRange(RecipeValidator.Validate(json,catalog));if(result.Report.HasErrors)return result;var recipe=VfxDomainParser.ParseRecipe(json).Value;var definition=IndependentContentCatalog.All.FirstOrDefault(v=>v.Id==recipe.Id);if(definition==null){result.Report.Add("E1831",ValidationSeverity.Error,"/id","Recipe is not registered in the independent-content catalog.",new JValue(recipe.Id));return result;}var recipeHash=RecipeCanonicalizer.ComputeSha256(json);var buildHash=Hash(recipeHash+"|"+CompilerVersion+"|"+VfxStyleSharedLibrary.DependencySignature()+"|"+Application.unityVersion);result.RecipeHash=recipeHash;result.BuildHash=buildHash;var folder="Assets/VFX/Generated/"+recipe.Id;var prefabPath=folder+"/VFX_"+recipe.Id+".prefab";result.PrefabPath=prefabPath;if(ReadManifest(recipe.Id)==buildHash&&AssetDatabase.LoadAssetAtPath<GameObject>(prefabPath)!=null){result.Succeeded=true;result.Unchanged=true;return result;}VfxStyleSharedLibrary.EnsureFolder(folder);var root=BuildRuntime(recipe,definition);try{if(PrefabUtility.SaveAsPrefabAsset(root,prefabPath)==null)throw new InvalidOperationException("Could not save "+prefabPath);}catch(Exception e){result.Report.Add("E1832",ValidationSeverity.Error,"/build",e.Message);return result;}finally{UnityEngine.Object.DestroyImmediate(root);}AssetDatabase.SaveAssets();var audit=VfxProductionRules.EnforceAndWriteManifest(recipe.Id,definition.Archetype,recipe.RecipeVersion,recipe.Revision,recipeHash,buildHash,CompilerVersion,prefabPath,folder,definition.Duration,sourceOverride);result.Report.AddRange(audit.Report);result.Succeeded=!result.Report.HasErrors;return result;
        }

        private static GameObject BuildRuntime(Recipe recipe,IndependentContentEntry definition)
        {
            var root=new GameObject("VFX_"+definition.Id);var renderers=new List<Renderer>();var particles=new List<ParticleSystem>();var lines=new List<LineRenderer>();var animated=new List<Transform>();var graphics=new List<Graphic>();Canvas canvas=null;var material=VfxStyleSharedLibrary.MaterialFor(definition.Style);if(definition.Family=="screen_ui"||definition.Family=="game_ui")BuildUi(root,definition,graphics,out canvas);else BuildWorld(root,definition,material,renderers,particles,lines,animated);
            var controller=root.AddComponent<PlannedContentVfxController>();var serialized=new SerializedObject(controller);serialized.FindProperty("contentId").stringValue=definition.Id;serialized.FindProperty("kind").enumValueIndex=(int)Kind(definition.Family);serialized.FindProperty("lifecycle").enumValueIndex=(int)definition.Lifecycle;serialized.FindProperty("duration").floatValue=definition.Duration;serialized.FindProperty("seed").longValue=Seed(definition.Id);SetObjects(serialized.FindProperty("renderers"),renderers.Cast<UnityEngine.Object>().ToArray());SetObjects(serialized.FindProperty("particles"),particles.Cast<UnityEngine.Object>().ToArray());SetObjects(serialized.FindProperty("lines"),lines.Cast<UnityEngine.Object>().ToArray());SetObjects(serialized.FindProperty("animatedTransforms"),animated.Cast<UnityEngine.Object>().ToArray());serialized.FindProperty("canvas").objectReferenceValue=canvas;SetObjects(serialized.FindProperty("graphics"),graphics.Cast<UnityEngine.Object>().ToArray());serialized.FindProperty("primary").colorValue=ParseColor(definition.Primary);serialized.FindProperty("secondary").colorValue=ParseColor(definition.Secondary);serialized.FindProperty("accent").colorValue=ParseColor(definition.Accent);SetParameters(serialized,JObject.Parse(definition.ParametersJson.Replace(":.",":0.")));serialized.ApplyModifiedPropertiesWithoutUndo();return root;
        }
        private static void BuildWorld(GameObject root,IndependentContentEntry definition,Material material,List<Renderer> renderers,List<ParticleSystem> particles,List<LineRenderer> lines,List<Transform> animated)
        {
            var meshes=new[]{VfxStyleSharedLibrary.RingPath,VfxStyleSharedLibrary.BurstPath,VfxStyleSharedLibrary.RibbonPath};for(var i=0;i<3;i++){var go=new GameObject("Layer_"+(i+1).ToString("00"));go.transform.SetParent(root.transform,false);go.transform.localScale=Vector3.one*(1-i*.18f);if(definition.Dimension=="3d")go.transform.localRotation=Quaternion.Euler(62,0,i*19);go.AddComponent<MeshFilter>().sharedMesh=AssetDatabase.LoadAssetAtPath<Mesh>(meshes[i]);var renderer=go.AddComponent<MeshRenderer>();renderer.sharedMaterial=material;renderer.sortingOrder=10+i;renderer.enabled=false;renderers.Add(renderer);animated.Add(go.transform);}if(definition.Id=="lifesteal_link_beam_2d"){var lineGo=new GameObject("RuntimeEndpointBeam");lineGo.transform.SetParent(root.transform,false);var line=lineGo.AddComponent<LineRenderer>();line.useWorldSpace=false;line.positionCount=16;line.widthMultiplier=.075f;line.numCapVertices=3;line.sharedMaterial=material;line.enabled=false;lines.Add(line);renderers.Add(line);}var count=definition.Family=="environment"?3:1;for(var i=0;i<count;i++){var go=new GameObject(definition.Family=="environment"?"WeatherLayer_"+(i+1):"FeedbackParticles");go.transform.SetParent(root.transform,false);var ps=go.AddComponent<ParticleSystem>();ps.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);var main=ps.main;main.playOnAwake=false;main.loop=definition.Lifecycle==PlannedContentLifecycle.Sustained;main.duration=Mathf.Max(.1f,definition.Duration);main.startLifetime=definition.Family=="environment"?new ParticleSystem.MinMaxCurve(.8f,1.6f):new ParticleSystem.MinMaxCurve(.18f,.5f);main.startSize=definition.Family=="environment"?new ParticleSystem.MinMaxCurve(.025f,.08f):new ParticleSystem.MinMaxCurve(.04f,.14f);main.startSpeed=definition.Family=="environment"?new ParticleSystem.MinMaxCurve(.2f,.6f):new ParticleSystem.MinMaxCurve(.5f,2.2f);main.maxParticles=definition.Family=="environment"?50:40;var emission=ps.emission;emission.rateOverTime=main.loop?18:0;if(!main.loop)emission.SetBursts(new[]{new ParticleSystem.Burst(0,(short)Math.Min(32,definition.Id.Contains("hit_flash")?5:18))});var shape=ps.shape;shape.shapeType=definition.Id=="parry_spark_impact_3d"?ParticleSystemShapeType.Cone:(definition.Family=="environment"?ParticleSystemShapeType.Box:ParticleSystemShapeType.Circle);shape.scale=definition.Family=="environment"?new Vector3(3,1.6f,.6f):Vector3.one;shape.radius=.6f;if(definition.Id=="parry_spark_impact_3d"){shape.angle=48f;var collision=ps.collision;collision.enabled=true;collision.type=ParticleSystemCollisionType.World;collision.mode=ParticleSystemCollisionMode.Collision3D;collision.bounce=.65f;collision.dampen=.12f;collision.lifetimeLoss=.18f;collision.maxCollisionShapes=4;}var psRenderer=go.GetComponent<ParticleSystemRenderer>();psRenderer.renderMode=ParticleSystemRenderMode.Mesh;psRenderer.mesh=AssetDatabase.LoadAssetAtPath<Mesh>(VfxStyleSharedLibrary.ShardPath);psRenderer.sharedMaterial=material;psRenderer.enabled=false;renderers.Add(psRenderer);particles.Add(ps);}
        }
        private static void BuildUi(GameObject root,IndependentContentEntry definition,List<Graphic> graphics,out Canvas canvas)
        {
            var rect=root.AddComponent<RectTransform>();rect.anchorMin=Vector2.zero;rect.anchorMax=Vector2.one;rect.offsetMin=Vector2.zero;rect.offsetMax=Vector2.zero;canvas=root.AddComponent<Canvas>();canvas.renderMode=RenderMode.ScreenSpaceOverlay;root.AddComponent<CanvasScaler>().uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;root.AddComponent<GraphicRaycaster>().enabled=false;var safe=new GameObject("SafeArea",typeof(RectTransform),typeof(RectMask2D));safe.transform.SetParent(root.transform,false);var safeRect=(RectTransform)safe.transform;safeRect.anchorMin=Vector2.zero;safeRect.anchorMax=Vector2.one;safeRect.offsetMin=new Vector2(12,12);safeRect.offsetMax=new Vector2(-12,-12);var count=definition.Id=="gacha_ten_sequence_ui"?8:6;for(var i=0;i<count;i++){var go=new GameObject("UiElement_"+(i+1).ToString("00"),typeof(RectTransform),typeof(CanvasRenderer),typeof(CoverageScreenFeedbackGraphic));go.transform.SetParent(safe.transform,false);var element=(RectTransform)go.transform;var col=i%3;var row=i/3;element.anchorMin=new Vector2(.08f+col*.32f,.08f+row*.46f);element.anchorMax=new Vector2(.28f+col*.32f,.42f+row*.46f);element.offsetMin=Vector2.zero;element.offsetMax=Vector2.zero;var graphic=go.GetComponent<CoverageScreenFeedbackGraphic>();graphic.raycastTarget=false;graphic.color=i%3==0?ParseColor(definition.Primary):i%3==1?ParseColor(definition.Secondary):ParseColor(definition.Accent);graphic.enabled=false;graphics.Add(graphic);}canvas.enabled=false;
        }
        private static void SetParameters(SerializedObject serialized,JObject parameters){var numbers=parameters.Properties().Where(v=>v.Value.Type==JTokenType.Integer||v.Value.Type==JTokenType.Float||v.Value.Type==JTokenType.Boolean).OrderBy(v=>v.Name,StringComparer.Ordinal).ToArray();var texts=parameters.Properties().Where(v=>v.Value.Type==JTokenType.String||v.Value.Type==JTokenType.Array).OrderBy(v=>v.Name,StringComparer.Ordinal).ToArray();var keys=serialized.FindProperty("parameterKeys");var values=serialized.FindProperty("parameterValues");keys.arraySize=values.arraySize=numbers.Length;for(var i=0;i<numbers.Length;i++){keys.GetArrayElementAtIndex(i).stringValue=numbers[i].Name;values.GetArrayElementAtIndex(i).floatValue=numbers[i].Value.Type==JTokenType.Boolean?((bool)numbers[i].Value?1:0):(float)numbers[i].Value;}var textKeys=serialized.FindProperty("textKeys");var textValues=serialized.FindProperty("textValues");textKeys.arraySize=textValues.arraySize=texts.Length;for(var i=0;i<texts.Length;i++){textKeys.GetArrayElementAtIndex(i).stringValue=texts[i].Name;textValues.GetArrayElementAtIndex(i).stringValue=texts[i].Value.Type==JTokenType.Array?texts[i].Value.ToString(Formatting.None):(string)texts[i].Value;}}
        private static PlannedContentKind Kind(string family){if(family=="environment")return PlannedContentKind.Environment;if(family=="hit_feedback")return PlannedContentKind.HitFeedback;if(family=="screen_ui")return PlannedContentKind.ScreenUi;return PlannedContentKind.GameUi;}
        private static void SetObjects(SerializedProperty property,UnityEngine.Object[] values){property.arraySize=values.Length;for(var i=0;i<values.Length;i++)property.GetArrayElementAtIndex(i).objectReferenceValue=values[i];}
        private static Color ParseColor(string text){Color value;return ColorUtility.TryParseHtmlString(text,out value)?value:Color.white;}
        private static string ReadManifest(string id){var path=VfxProjectRules.ManifestAbsolutePath(id);if(!File.Exists(path))return null;try{return(string)JObject.Parse(File.ReadAllText(path))["buildHash"];}catch{return null;}}
        private static uint Seed(string id){unchecked{uint hash=2166136261;foreach(var c in id){hash^=c;hash*=16777619;}return hash;}}
        private static string Hash(string value){using(var sha=SHA256.Create())return string.Concat(sha.ComputeHash(Encoding.UTF8.GetBytes(value)).Select(v=>v.ToString("x2",CultureInfo.InvariantCulture)));}
        private static string Absolute(string path){return Path.GetFullPath(Path.Combine(Directory.GetParent(Application.dataPath).FullName,path.Replace('/',Path.DirectorySeparatorChar)));}
    }

    public static class IndependentContentAuthoring
    {
        public const string RecipeRoot="Assets/VFX/Recipes/Independent";public const string PatchRoot="Assets/VFX/Recipes/Patches";public const string PreviewRoot="Assets/VFX/Preview";
        private static readonly Dictionary<string,string> PreviewNames=new Dictionary<string,string>(StringComparer.Ordinal){{"environment","VFXPREVIEW_Environment.unity"},{"hit_feedback","VFXPREVIEW_HitFeedback.unity"},{"screen_ui","VFXPREVIEW_ScreenUI.unity"},{"game_ui","VFXPREVIEW_GameUI.unity"}};
        [MenuItem("Tools/VFX Composer/Content/Build W11 W12 W14 W17")]
        public static void BuildAll(){BuildEntries();foreach(var group in PreviewNames.Keys)BuildPreview(group);AssetDatabase.SaveAssets();AssetDatabase.Refresh();}
        public static void BuildEntries(){WriteAllRecipes();AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);foreach(var entry in IndependentContentCatalog.All){var result=IndependentContentCompiler.BuildAsset(RecipePath(entry));if(!result.Succeeded)throw new InvalidOperationException(entry.Id+": "+string.Join(" | ",result.Report.Entries.Select(v=>v.Code+" "+v.Path+" "+v.Message)));}AssetDatabase.SaveAssets();AssetDatabase.Refresh();}
        public static void WriteAllRecipes(){VfxStyleSharedLibrary.EnsureFolder(RecipeRoot);VfxStyleSharedLibrary.EnsureFolder(PatchRoot);foreach(var entry in IndependentContentCatalog.All){var folder=RecipeRoot+"/"+Folder(entry.Group);VfxStyleSharedLibrary.EnsureFolder(folder);Write(folder+"/"+entry.Id+".default.json",Recipe(entry));WritePatch(entry);}}
        public static string RecipePath(IndependentContentEntry entry){return RecipeRoot+"/"+Folder(entry.Group)+"/"+entry.Id+".default.json";}
        public static string PreviewPath(string group){return PreviewRoot+"/"+PreviewNames[group];}
        private static JObject Recipe(IndependentContentEntry entry){return new JObject{{"recipeVersion",1},{"revision",1},{"id",entry.Id},{"name",Title(entry.Id)},{"dimension",entry.Dimension},{"archetype",entry.Archetype},{"style",new JObject{{"token",entry.Style},{"palette",new JObject{{"primary",entry.Primary},{"secondary",entry.Secondary},{"accent",entry.Accent}}},{"outline",.12},{"shading_steps",4},{"noise_scale",1.2},{"glow_strength",1.1}}},{"behavior",JObject.Parse(entry.BehaviorJson.Replace(":.",":0."))},{"content",new JObject{{"family",entry.Family},{"parameters",JObject.Parse(entry.ParametersJson.Replace(":.",":0."))}}},{"targetProfile","mobile_medium"},{"randomSeed",Seed(entry.Id)},{"stages",Stages(entry)},{"metadata",new JObject{{"createdBy","w11-w17-independent-content"},{"templateCatalogVersion","1.0.0"}}}};}
        private static JArray Stages(IndependentContentEntry entry){var d=entry.Dimension;var core="PFT_"+(d=="2d"?"2D":"3D")+"_FireCore";var trail="PFT_"+(d=="2d"?"2D":"3D")+"_FireTrail";var particles="PFT_"+(d=="2d"?"2D":"3D")+"_Embers";var shock="PFT_"+(d=="2d"?"2D":"3D")+"_Shockwave";return new JArray{new JObject{{"id","main"},{"trigger",entry.Archetype=="impact"?"on_hit":"manual"},{"duration",entry.Duration},{"enabled",true},{"modules",new JArray{Module("body","energy_body",core,new JObject{{"scale",1.0}}),Module("flow","motion_trail",trail,new JObject{{"time",.3},{"width",.25}},"body"),Module("secondary","secondary_particles",particles,new JObject{{"rate",10},{"lifetime",.55}},"body"),Module("accent","shockwave",shock,new JObject{{"lifetime",.3},{"endSize",2.1}})}}}};}
        private static JObject Module(string id,string kind,string template,JObject parameters,string attach=null){var value=new JObject{{"id",id},{"kind",kind},{"templateId",template},{"parameters",parameters},{"enabled",true}};if(attach!=null)value["attachTo"]=attach;return value;}
        private static void WritePatch(IndependentContentEntry entry){ContentDefinition definition;ContentParameterRegistry.TryGet(entry.Id,out definition);var parameter=definition.Parameters.Values.OrderBy(v=>v.Name,StringComparer.Ordinal).First();var values=JObject.Parse(entry.ParametersJson.Replace(":.",":0."));var current=values[parameter.Name];JToken alternative;if(parameter.Kind==ContentParameterKind.Boolean)alternative=new JValue(!(bool)current);else if(parameter.Kind==ContentParameterKind.Enum)alternative=new JValue(parameter.Values.First(v=>v!=(string)current));else if(parameter.Kind==ContentParameterKind.IntegerArray){var array=(JArray)current.DeepClone();array[0]=(int)array[0]==(int)parameter.Max?(int)parameter.Min:(int)parameter.Max;alternative=array;}else if(parameter.Kind==ContentParameterKind.Integer)alternative=new JValue((int)current==(int)parameter.Max?(int)parameter.Min:(int)parameter.Max);else if(parameter.Kind==ContentParameterKind.Number)alternative=new JValue(Math.Abs((double)current-parameter.Max)<.0001?parameter.Min:parameter.Max);else alternative=new JValue((string)current+"_variant");Write(PatchRoot+"/"+entry.Id+".semantic.patch.json",new JArray{new JObject{{"op","set_content_param"},{"path","/content/parameters/"+parameter.Name},{"value",alternative}}});}
        private static void BuildPreview(string group)
        {
            VfxStyleSharedLibrary.EnsureFolder(PreviewRoot);var scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var cameraGo=new GameObject("IndependentContentReviewCamera");var camera=cameraGo.AddComponent<Camera>();camera.tag="MainCamera";camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.015f,.018f,.025f);camera.orthographic=true;camera.orthographicSize=group=="game_ui"?5.8f:4.7f;camera.transform.position=new Vector3(0,0,-12);camera.allowHDR=false;camera.allowMSAA=false;var entries=IndependentContentCatalog.Group(group).ToArray();var controllers=new List<PlannedContentVfxController>();for(var i=0;i<entries.Length;i++){var entry=entries[i];var row=i/3;var col=i%3;var cell=new GameObject("Cell_"+(i+1).ToString("00")+"_"+entry.Id);cell.transform.position=new Vector3((col-1)*3.2f,2.8f-row*2.45f,0);var prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/VFX/Generated/"+entry.Id+"/VFX_"+entry.Id+".prefab");var instance=(GameObject)PrefabUtility.InstantiatePrefab(prefab,scene);instance.transform.SetParent(cell.transform,false);instance.transform.localScale=Vector3.one*.72f;var controller=instance.GetComponent<PlannedContentVfxController>();controllers.Add(controller);var canvas=instance.GetComponent<Canvas>();if(canvas!=null){canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=camera;canvas.planeDistance=2;var safe=instance.transform.Find("SafeArea") as RectTransform;if(safe!=null){safe.anchorMin=new Vector2(col/3f,1-(row+1)/4f);safe.anchorMax=new Vector2((col+1)/3f,1-row/4f);safe.offsetMin=new Vector2(18,36);safe.offsetMax=new Vector2(-18,-22);}}else{var label=new GameObject("Label");label.transform.SetParent(cell.transform,false);label.transform.localPosition=new Vector3(0,-1.05f,0);var text=label.AddComponent<TextMesh>();text.text=(i+1)+" "+entry.Id;text.anchor=TextAnchor.MiddleCenter;text.fontSize=40;text.characterSize=.032f;text.color=new Color(.68f,.75f,.84f);}}
            var driverGo=new GameObject("PlannedContentPreviewDriver");var driver=driverGo.AddComponent<PlannedContentPreviewDriver>();var serialized=new SerializedObject(driver);var property=serialized.FindProperty("entries");property.arraySize=controllers.Count;for(var i=0;i<controllers.Count;i++)property.GetArrayElementAtIndex(i).objectReferenceValue=controllers[i];serialized.ApplyModifiedPropertiesWithoutUndo();EditorSceneManager.SaveScene(scene,PreviewPath(group));
        }
        private static string Folder(string group){return group=="environment"?"Environment":group=="hit_feedback"?"HitFeedback":group=="screen_ui"?"ScreenUI":"GameUI";}
        private static string Title(string id){return string.Join(" ",id.Split('_').Select(v=>v.Length==0?v:char.ToUpperInvariant(v[0])+v.Substring(1)));}
        private static uint Seed(string id){unchecked{uint hash=2166136261;foreach(var c in id){hash^=c;hash*=16777619;}return hash;}}
        private static void Write(string path,JToken token){var absolute=Path.GetFullPath(Path.Combine(Directory.GetParent(Application.dataPath).FullName,path.Replace('/',Path.DirectorySeparatorChar)));Directory.CreateDirectory(Path.GetDirectoryName(absolute));File.WriteAllText(absolute,token.ToString(Formatting.Indented).Replace("\r\n","\n"));}
    }
